<script setup lang="ts">
import { ref } from 'vue'; import { useRouter } from 'vue-router'; import BaseButton from '../../components/ui/BaseButton.vue'; import OnboardingOption from '../../components/onboarding/OnboardingOption.vue'; import { useCompanyOnboardingStore } from '../../stores/companyOnboarding'; import { isCnpj, isCpf, maskCnpj, maskCpf } from '../../utils/validation'
const router = useRouter(); const store = useCompanyOnboardingStore(); const error = ref('')
function next() { const company = store.state.company; error.value = !company.name.trim() ? 'Informe o nome da empresa.' : !company.document || (company.documentType === 'cnpj' ? !isCnpj(company.document) : !isCpf(company.document)) ? `${company.documentType === 'cnpj' ? 'CNPJ' : 'CPF'} inválido.` : ''; if (error.value) return; store.nextStep(); router.push('/cadastro/contato') }
</script>
<template><section><h1 class="text-3xl font-medium tracking-tight sm:text-4xl">Qual é o nome da sua empresa?</h1><div class="mt-10 space-y-5"><label class="block"><span class="text-sm font-medium">Razão social / Nome</span><input v-model="store.state.company.name" class="mt-2 h-14 w-full rounded-lg border border-neutral-300 px-4 outline-none focus:border-neutral-900 focus:ring-2 focus:ring-lime-200" /></label><label class="block"><span class="text-sm font-medium">Nome fantasia</span><input v-model="store.state.company.tradeName" class="mt-2 h-14 w-full rounded-lg border border-neutral-300 px-4 outline-none focus:border-neutral-900 focus:ring-2 focus:ring-lime-200" /></label><h2 class="pt-3 text-lg font-medium">Como sua empresa é registrada?</h2><div class="grid gap-3 sm:grid-cols-2"><OnboardingOption label="CNPJ" value="cnpj" :selected="store.state.company.documentType === 'cnpj'" @select="store.updateCompany({ documentType: 'cnpj', document: '' })" /><OnboardingOption label="Pessoa física" value="cpf" :selected="store.state.company.documentType === 'cpf'" @select="store.updateCompany({ documentType: 'cpf', document: '' })" /></div><label class="block"><span class="text-sm font-medium">{{ store.state.company.documentType === 'cnpj' ? 'CNPJ' : 'CPF' }}</span><input :value="store.state.company.document" inputmode="numeric" class="mt-2 h-14 w-full rounded-lg border border-neutral-300 px-4 outline-none focus:border-neutral-900 focus:ring-2 focus:ring-lime-200" :placeholder="store.state.company.documentType === 'cnpj' ? '00.000.000/0000-00' : '000.000.000-00'" @input="store.updateCompany({ document: store.state.company.documentType === 'cnpj' ? maskCnpj(($event.target as HTMLInputElement).value) : maskCpf(($event.target as HTMLInputElement).value) })" /></label><p v-if="error" class="text-sm text-red-600">{{ error }}</p><BaseButton class="min-h-[56px] w-full text-base sm:min-h-[68px] sm:text-lg" @click="next">Continuar</BaseButton></div></section></template>
